"use strict";
import { Lock, Check, Clock } from "react-feather";
import styled from "styled-components";
import { Flex, Separator, SpinningLoader, StarBorderButton, Text, styled as UiStyled, useSporeColors } from "ui/src";
import { colors as BaseColor } from "ui/src/theme";
const ItemWrapper = UiStyled(Flex, {
  row: true,
  gap: "$gap8",
  alignItems: "center"
});
const IconWrapper = UiStyled(Flex, {
  width: 28,
  height: 28,
  borderRadius: "$roundedFull",
  backgroundColor: "$surface3",
  centered: true
});
const StepText = UiStyled(Text, {
  variants: {
    status: {
      complete: {
        color: "$accent1"
      },
      pending: {
        color: "$neutral2"
      },
      blocked: {
        color: "$statusCritical"
      }
    }
  }
});
const DepositButton = styled.button`
  all: unset;
  padding: 16px 10px;
  background-color: ${({ theme, disabled }) => disabled ? theme.surface3 : theme.accent1};
  color: ${({ theme, disabled }) => disabled ? theme.neutral3 : theme.surface1};
  border-radius: 12px;
  cursor: ${({ disabled }) => disabled ? "not-allowed" : "pointer"};
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.2s ease;
  opacity: ${({ disabled }) => disabled ? 0.6 : 1};
  &:hover {
    opacity: ${({ disabled }) => disabled ? 0.6 : 0.8};
  }
`;
export default function RelayDepositReviewer({
  selectedLock,
  selectedRelay,
  hasSelectedLockVoted,
  depositDisabledReason,
  onDeposit,
  onResetVotes,
  isDepositing,
  isResettingVotes,
  transactionState
}) {
  const colors = useSporeColors();
  const steps = [
    {
      icon: Lock,
      text: selectedLock ? `Selected lock #${selectedLock.id}` : "Select the lock you want to deposit",
      status: selectedLock ? "complete" : "pending"
    },
    {
      icon: Check,
      text: selectedRelay ? `Selected relay #${selectedRelay.id}` : "Choose a relay strategy",
      status: selectedRelay ? "complete" : "pending"
    },
    {
      icon: Check,
      text: "Review unlock date extension to maximum duration",
      status: selectedLock ? "complete" : "pending"
    }
  ];
  if (hasSelectedLockVoted) {
    steps.push({
      icon: Lock,
      text: "Reset votes for this lock to enable relay deposit",
      status: isResettingVotes ? "pending" : "blocked"
    });
  }
  steps.push({
    icon: Clock,
    text: transactionState.isConfirming || isDepositing ? "Transaction pending on-chain..." : "Confirm deposit transaction",
    status: transactionState.isSuccess && !isDepositing ? "complete" : "pending"
  });
  const buttonDisabled = isDepositing || transactionState.isConfirming || !selectedLock || !selectedRelay || hasSelectedLockVoted || Boolean(depositDisabledReason);
  const handleDepositClick = () => {
    if (!buttonDisabled) {
      onDeposit().catch(() => void 0);
    }
  };
  const handleResetClick = () => {
    if (!onResetVotes || isResettingVotes || transactionState.isLoading || transactionState.isConfirming) {
      return;
    }
    onResetVotes().catch(() => void 0);
  };
  return <Flex
    flexDirection="column"
    p={"$spacing16"}
    borderRadius={"$rounded12"}
    gap={"$gap24"}
    borderWidth={1}
    borderColor={"$surface3"}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
      <Text variant="buttonLabel1">Relay Deposit</Text>

      <Flex flexDirection="column">
        {steps.map((item, index) => <Flex key={`${item.text}-${index}`}>
            {index > 0 && <Separator left={14} vertical minHeight={22} width={2} borderColor={"$surface3"} />}

            <ItemWrapper>
              <IconWrapper>
                <Flex>
                  <item.icon
    size={14}
    color={item.status === "complete" ? BaseColor.greenVibrant : item.status === "blocked" ? BaseColor.redVibrant : BaseColor.brownVibrant}
  />
                </Flex>
              </IconWrapper>

              <StepText variant="body3" status={item.status}>
                {item.text}
              </StepText>
            </ItemWrapper>
          </Flex>)}
      </Flex>

      {hasSelectedLockVoted && <Flex flexDirection="column" gap="$gap8">
          <Text variant="body4" color="$statusCritical">
            This lock has already voted in the current epoch. Reset votes to proceed with the relay deposit.
          </Text>
          {onResetVotes && <StarBorderButton
    as="button"
    speed="3s"
    disabled={isResettingVotes || transactionState.isLoading || transactionState.isConfirming}
    onClick={handleResetClick}
  >
              <Flex row alignItems="center" gap="$gap8">
                {isResettingVotes ? <SpinningLoader size={14} /> : <Check size={14} color={colors.neutral1.val} />}
                <Text variant="buttonLabel4" color="inherit">
                  {isResettingVotes ? "Resetting Votes\u2026" : "Reset Votes"}
                </Text>
              </Flex>
            </StarBorderButton>}
        </Flex>}

      {depositDisabledReason && !hasSelectedLockVoted && <Text variant="body4" color="$statusWarning">
          {depositDisabledReason}
        </Text>}

      <DepositButton onClick={handleDepositClick} disabled={buttonDisabled}>
        <Flex row alignItems="center" gap="$gap8">
          {(isDepositing || transactionState.isConfirming || transactionState.isLoading) && <SpinningLoader size={16} />}
          <Text variant="buttonLabel2" color="inherit">
            {isDepositing || transactionState.isConfirming ? "Depositing\u2026" : "Deposit to Relay"}
          </Text>
        </Flex>
      </DepositButton>
    </Flex>;
}
