"use strict";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useLocation } from "react-router-dom";
import { useAccount, useChainId } from "wagmi";
import { Flex } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useVeABXUserLocks, useManagedVeABXRelays } from "hooks/useVeABXLocks";
import { useManagedDeposits, useRelayStatuses } from "hooks/useManagedDeposits";
import { useVoterContract } from "hooks/useVoterContract";
import { useVotedLocks } from "hooks/useVotedLocks";
import { calculateTimeUntilUnlock, formatABXAmount } from "utils/lockCalculations";
import SelectYourLock from "./components/SelectYourLock";
import RelayDepositReviewer from "./components/RelayDepositReviewer";
export default function DepositLock() {
  const { address: account } = useAccount();
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [rawChainId]);
  const location = useLocation();
  const searchParams = useMemo(() => new URLSearchParams(location.search), [location.search]);
  const queryLockId = searchParams.get("lockId") ?? void 0;
  const queryRelayId = searchParams.get("relayId") ?? void 0;
  const {
    data: userLocks = [],
    isLoading: locksLoading,
    refetch: refetchUserLocks
  } = useVeABXUserLocks(account, true, resolvedChainId);
  const { depositMap, isLoading: depositsLoading, refetch: refetchManagedStatus } = useManagedDeposits(userLocks);
  const { hasVoted, refetch: refetchVotes } = useVotedLocks(userLocks);
  const { data: relays = [], isLoading: relaysLoading } = useManagedVeABXRelays(true, resolvedChainId);
  const relayIds = useMemo(() => relays.map((relay) => relay.id), [relays]);
  const { statusMap: relayStatusMap } = useRelayStatuses(relayIds);
  const eligibleLocks = useMemo(
    () => userLocks.filter((lock) => {
      const depositInfo = depositMap.get(lock.id);
      const isExpired = !lock.permanent && calculateTimeUntilUnlock(lock.lockEnd).expired;
      return !lock.managed && !depositInfo?.isDeposited && !isExpired;
    }),
    [userLocks, depositMap]
  );
  const activeRelays = useMemo(
    () => relays.filter((relay) => relayStatusMap.get(relay.id)?.isActive !== false),
    [relays, relayStatusMap]
  );
  const lockOptions = useMemo(
    () => eligibleLocks.map((lock) => ({
      value: lock.id,
      label: `Lock #${lock.id} \xB7 ${formatABXAmount(BigInt(lock.amount))} ABX`
    })),
    [eligibleLocks]
  );
  const relayOptions = useMemo(
    () => activeRelays.map((relay) => ({
      value: relay.id,
      label: `Relay #${relay.id}`
    })),
    [activeRelays]
  );
  const [selectedLockId, setSelectedLockId] = useState();
  const [selectedRelayId, setSelectedRelayId] = useState();
  const [pendingDeposit, setPendingDeposit] = useState(null);
  const [termsAccepted, setTermsAccepted] = useState(false);
  useEffect(() => {
    if (!selectedLockId && queryLockId && eligibleLocks.some((lock) => lock.id === queryLockId)) {
      setSelectedLockId(queryLockId);
    }
  }, [eligibleLocks, queryLockId, selectedLockId]);
  useEffect(() => {
    setTermsAccepted(false);
  }, [selectedLockId]);
  useEffect(() => {
    if (!selectedLockId && eligibleLocks.length > 0) {
      setSelectedLockId(eligibleLocks[0].id);
    } else if (selectedLockId && !eligibleLocks.some((lock) => lock.id === selectedLockId)) {
      setSelectedLockId(eligibleLocks[0]?.id);
    }
  }, [eligibleLocks, selectedLockId]);
  useEffect(() => {
    if (!selectedRelayId && queryRelayId && activeRelays.some((relay) => relay.id === queryRelayId)) {
      setSelectedRelayId(queryRelayId);
    }
  }, [activeRelays, queryRelayId, selectedRelayId]);
  useEffect(() => {
    if (!selectedRelayId && activeRelays.length > 0) {
      setSelectedRelayId(activeRelays[0].id);
    } else if (selectedRelayId && !activeRelays.some((relay) => relay.id === selectedRelayId)) {
      setSelectedRelayId(activeRelays[0]?.id);
    }
  }, [activeRelays, selectedRelayId]);
  const selectedLock = useMemo(
    () => userLocks.find((lock) => lock.id === selectedLockId),
    [userLocks, selectedLockId]
  );
  const selectedRelay = useMemo(
    () => relays.find((relay) => relay.id === selectedRelayId),
    [relays, selectedRelayId]
  );
  const hasSelectedLockVoted = selectedLockId ? hasVoted(selectedLockId) : false;
  const selectedRelayStatus = selectedRelayId ? relayStatusMap.get(selectedRelayId) : void 0;
  const depositDisabledReason = useMemo(() => {
    if (!account) {
      return "Connect your wallet to deposit into a relay.";
    }
    if (!selectedLock) {
      return eligibleLocks.length === 0 ? "No eligible locks available for relay deposit." : "Select a lock to deposit.";
    }
    if (!selectedLock) {
      return eligibleLocks.length === 0 ? "No eligible locks available for relay deposit." : "Select a lock to deposit.";
    }
    const lockExpired = !selectedLock.permanent && calculateTimeUntilUnlock(selectedLock.lockEnd).expired;
    if (lockExpired) {
      return "This lock has expired. Withdraw and re-lock before depositing into a relay.";
    }
    if (!selectedRelay) {
      return activeRelays.length === 0 ? "No active relays available." : "Select a relay strategy.";
    }
    if (selectedRelayStatus && !selectedRelayStatus.isActive) {
      return "Selected relay is currently inactive.";
    }
    if (!termsAccepted) {
      return "Acknowledge the relay deposit terms before proceeding.";
    }
    return void 0;
  }, [account, selectedLock, eligibleLocks.length, hasSelectedLockVoted, selectedRelay, activeRelays.length, selectedRelayStatus, termsAccepted]);
  const { depositManaged, resetVotes, transactionState } = useVoterContract();
  const isDepositing = Boolean(pendingDeposit) && (transactionState.isLoading || transactionState.isConfirming);
  const [pendingResetLockId, setPendingResetLockId] = useState(null);
  const isResettingVotes = Boolean(pendingResetLockId) && (transactionState.isLoading || transactionState.isConfirming);
  const handleDeposit = useCallback(async () => {
    if (!selectedLock || !selectedRelay) {
      return;
    }
    setPendingDeposit({ lockId: selectedLock.id, relayId: selectedRelay.id });
    try {
      await depositManaged({
        tokenId: selectedLock.id,
        managedTokenId: selectedRelay.id,
        relayName: `mveABX #${selectedRelay.id}`
      });
    } catch (error) {
      setPendingDeposit(null);
      throw error;
    }
  }, [selectedLock, selectedRelay, depositManaged]);
  const handleResetVotes = useCallback(async () => {
    if (!selectedLock) {
      return;
    }
    setPendingResetLockId(selectedLock.id);
    try {
      await resetVotes(selectedLock.id);
    } catch (error) {
      setPendingResetLockId(null);
      throw error;
    }
  }, [selectedLock, resetVotes]);
  useEffect(() => {
    if (!pendingDeposit) {
      return;
    }
    if (transactionState.isSuccess) {
      refetchManagedStatus();
      refetchUserLocks();
      refetchVotes();
      setPendingDeposit(null);
    } else if (transactionState.error && !transactionState.isLoading && !transactionState.isConfirming) {
      setPendingDeposit(null);
    }
  }, [
    pendingDeposit,
    transactionState.isSuccess,
    transactionState.error,
    transactionState.isLoading,
    transactionState.isConfirming,
    refetchManagedStatus,
    refetchUserLocks,
    refetchVotes
  ]);
  useEffect(() => {
    if (!pendingResetLockId) {
      return;
    }
    if (transactionState.isSuccess) {
      refetchVotes();
      refetchUserLocks();
      setPendingResetLockId(null);
    } else if (transactionState.error && !transactionState.isLoading && !transactionState.isConfirming) {
      setPendingResetLockId(null);
    }
  }, [
    pendingResetLockId,
    transactionState.isSuccess,
    transactionState.error,
    transactionState.isLoading,
    transactionState.isConfirming,
    refetchVotes,
    refetchUserLocks
  ]);
  const isLoadingData = locksLoading || depositsLoading || relaysLoading;
  return <Flex
    gap={"$gap24"}
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={1024}
    pb={"$spacing40"}
    $platform-web={{
      display: "grid",
      gridTemplateColumns: "4fr 3fr"
    }}
    $md={{
      gridTemplateColumns: "1fr"
    }}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
  >
      <SelectYourLock
    lockOptions={lockOptions}
    selectedLockId={selectedLockId}
    onSelectLock={setSelectedLockId}
    selectedLock={selectedLock}
    relayOptions={relayOptions}
    selectedRelayId={selectedRelayId}
    onSelectRelay={setSelectedRelayId}
    selectedRelay={selectedRelay}
    isLoading={isLoadingData}
    termsAccepted={termsAccepted}
    onToggleTerms={() => setTermsAccepted((prev) => !prev)}
  />
      <RelayDepositReviewer
    selectedLock={selectedLock}
    selectedRelay={selectedRelay}
    hasSelectedLockVoted={hasSelectedLockVoted}
    depositDisabledReason={depositDisabledReason}
    onDeposit={handleDeposit}
    onResetVotes={hasSelectedLockVoted ? handleResetVotes : void 0}
    isDepositing={isDepositing}
    isResettingVotes={isResettingVotes}
    transactionState={transactionState}
  />
    </Flex>;
}
